import urllib.request
import urllib.parse
import json
import re

books = [
    ("Fire and Blood", "George R. R. Martin"),
    ("Song of Solomon", "Toni Morrison"),
    ("The Lost Symbol", "Dan Brown"),
    ("2001: A Space Odyssey", "Arthur C. Clarke"),
    ("American Gods", "Neil Gaiman"),
    ("Out of the Silent Planet", "C.S. Lewis"),
    ("The Andromeda Strain", "Michael Crichton"),
    ("Brave New World", "Aldous Huxley"),
    ("Silence", "Shusaku Endo"),
    ("The Shining", "Stephen King"),
]

def search(q):
    url = f"https://api.howlongtoread.com/books/search/{urllib.parse.quote(q)}"
    req = urllib.request.Request(url, headers={"User-Agent":"Mozilla/5.0"})
    return json.loads(urllib.request.urlopen(req).read())

def get_book(book_id):
    url = f"https://api.howlongtoread.com/books/id/{book_id}"
    req = urllib.request.Request(url, headers={"User-Agent":"Mozilla/5.0"})
    return json.loads(urllib.request.urlopen(req).read())

results = {}
for title, author in books:
    hits = search(title)
    # find best match: same title and author contains
    pick = None
    for h in hits:
        if h['title'].strip().lower() == title.strip().lower() and author.lower().split()[0] in h.get('author','').lower():
            pick = h
            break
    if not pick:
        # try first one with that author
        for h in hits:
            if author.lower().split()[0] in h.get('author','').lower():
                pick = h
                break
    if not pick:
        pick = hits[0] if hits else None
    if pick:
        d = get_book(pick['id'])
        wc = d.get('wordCount')
        wc_val = wc.get('value') if isinstance(wc, dict) else wc
        results[title] = {
            'id': pick['id'],
            'title_match': d.get('title'),
            'author_match': d.get('author'),
            'wordCount': wc_val,
            'numPages': d.get('numPages'),
            'readingTime': d.get('readingTime'),
        }
    else:
        results[title] = None

for k,v in results.items():
    print(f"{k}: {v}")
EOF

